      if (!extra) return doc3;
      const existing = new Set((doc3.fields || []).map((f) => f.key));
      const additions = extra().filter((f) => {
        if (existing.has(f.key)) return false;
        existing.add(f.key);
        return true;
      });
      if (!additions.length) return doc3;
      return {
        ...doc3,
        fields: [...doc3.fields || [], ...additions],
        // The clinical references the note content was built from, recorded on the
        // template so the note header and PDF can state them without re-typing.
        guidelineBasis: ["ACC", "AHA", "ESC", "WHO ICD-11 MMS"]
      };
